class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.tree = [0] * (4 * self.n)
        self.build(0, 0, self.n - 1, data)

    def build(self, node, l, r, data):
        if l == r:
            self.tree[node] = data[l]
        else:
            mid = (l + r) // 2
            self.build(2*node+1, l, mid, data)
            self.build(2*node+2, mid+1, r, data)
            self.tree[node] = self.tree[2*node+1] + self.tree[2*node+2]

    def update(self, node, l, r, idx, val):
        if l == r:
            self.tree[node] = val
        else:
            mid = (l + r) // 2
            if idx <= mid:
                self.update(2*node+1, l, mid, idx, val)
            else:
                self.update(2*node+2, mid+1, r, idx, val)
            self.tree[node] = self.tree[2*node+1] + self.tree[2*node+2]

    def query(self, node, l, r, ql, qr):
        if ql > r or qr < l:
            return 0
        if ql <= l and r <= qr:
            return self.tree[node]
        mid = (l + r) // 2
        return self.query(2*node+1, l, mid, ql, qr) + self.query(2*node+2, mid+1, r, ql, qr)

class LazySegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)
        self.lazy = [0] * (4 * n)

    def apply(self, node, l, r, val):
        self.tree[node] += val * (r - l + 1)
        self.lazy[node] += val

    def push(self, node, l, r):
        if self.lazy[node] != 0:
            mid = (l + r) // 2
            self.apply(2*node+1, l, mid, self.lazy[node])
            self.apply(2*node+2, mid+1, r, self.lazy[node])
            self.lazy[node] = 0

    def range_add(self, node, l, r, ql, qr, val):
        if ql > r or qr < l:
            return
        if ql <= l and r <= qr:
            self.apply(node, l, r, val)
            return
        self.push(node, l, r)
        mid = (l + r) // 2
        self.range_add(2*node+1, l, mid, ql, qr, val)
        self.range_add(2*node+2, mid+1, r, ql, qr, val)
        self.tree[node] = self.tree[2*node+1] + self.tree[2*node+2]

class MinSegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.tree = [float('inf')] * (4 * self.n)
        self.build(0, 0, self.n - 1, data)

    def build(self, node, l, r, data):
        if l == r:
            self.tree[node] = data[l]
        else:
            mid = (l + r) // 2
            self.build(2*node+1, l, mid, data)
            self.build(2*node+2, mid+1, r, data)
            self.tree[node] = min(self.tree[2*node+1], self.tree[2*node+2])

    def query(self, node, l, r, ql, qr):
        if ql > r or qr < l:
            return float('inf')
        if ql <= l and r <= qr:
            return self.tree[node]
        mid = (l + r) // 2
        return min(self.query(2*node+1, l, mid, ql, qr), 
                   self.query(2*node+2, mid+1, r, ql, qr))
